      "trawlers": { fr: "chalutiers", pos: "nom pluriel", ipa: "/ˈtrɔː.ləz/", tip: "Bateaux de pêche équipés de grands filets traînants." },
      "breeding": { fr: "reproduction / fraie", pos: "nom ou adjectif", ipa: "/ˈbriː.dɪŋ/", tip: "Période ou lieu où les animaux marins s'accouplent et pondent leurs œufs." },
      "despair": { fr: "désespoir", pos: "nom", ipa: "/dɪˈspeə/", tip: "Sentiment d'impuissance et de perte totale d'espoir." },
      "ominous": { fr: "menaçant / de mauvais augure", pos: "adjectif", ipa: "/ˈɒm.ɪ.nəs/", tip: "Donnant l'impression troublante qu'un malheur ou danger approche." },
      "tempest": { fr: "tempête violente", pos: "nom", ipa: "/ˈtem.pɪst/", tip: "Orage extrêmement puissant accompagné de vents furieux et de fortes pluies." },
