// Helper: Détection automatique de la catégorie grammaticale par suffixes
function guessPartOfSpeech(word) {
  if (!word) return "mot";
  if (word.endsWith("ly")) return "adverbe";
  if (word.endsWith("ing")) return "verbe (-ing)";
  if (word.endsWith("ed")) return "verbe (passé)";
  if (word.endsWith("tion") || word.endsWith("sion") || word.endsWith("ment") || word.endsWith("ness") || word.endsWith("ity")) return "nom";
  if (word.endsWith("ful") || word.endsWith("less") || word.endsWith("ous") || word.endsWith("ive") || word.endsWith("able") || word.endsWith("ible")) return "adjectif";
  if (word.endsWith("est")) return "superlatif";
  if (word.endsWith("er")) return "comparatif / nom";
  if (word.endsWith("s")) return "nom pluriel ou verbe";
  return "mot anglais";
}

// Helper: Word lookup combinant dictionnaire bilingue complet + vocabulaire d'histoire + lemmatisation intelligente
window.CAA.lookupStoryWord = function (rawWord, storyVocab) {
  if (!rawWord) return null;
  
  // Normaliser le mot (gérer apostrophes courbes et ponctuation)
  let clean = rawWord.toLowerCase().replace(/[’‘]/g, "'").replace(/[^a-z'-]/g, "").trim();
  clean = clean.replace(/^-+|-+$/g, ""); // retirer tirets aux extrémités
  if (!clean) return null;

  // 1. Résolution prioritaire des formes contractées (can't, didn't, it's, i'm, let's...)
  if (window.CAA.contractionsMap && window.CAA.contractionsMap[clean]) {
    return Object.assign({ word: clean }, window.CAA.contractionsMap[clean]);
  }
  // Gérer aussi le cas sans apostrophe (ex: cant, didnt)
  const noApos = clean.replace(/'/g, "");
  if (window.CAA.contractionsMap && window.CAA.contractionsMap[noApos]) {
    return Object.assign({ word: clean }, window.CAA.contractionsMap[noApos]);
  }

  // 2. Gestion du génitif saxon possessif ('s)
  if (clean.endsWith("'s")) {
    const rootName = clean.replace(/'s$/, "");
    return {
      word: clean,
      fr: `de ${rootName} (marque de possession)`,
      pos: "génitif possessif ('s)",
      ipa: "",
      tip: `Indique que quelque chose appartient à ${rootName}.`
    };
  }

  // 3. Correspondance directe dans le vocabulaire spécifique de l'histoire
  if (storyVocab && storyVocab[clean]) {
    return Object.assign({ word: clean }, storyVocab[clean]);
  }

  // 4. Correspondance directe dans le grand dictionnaire bilingue CAA.enFrDict
  if (window.CAA.enFrDict && window.CAA.enFrDict[clean]) {
    return Object.assign({ word: clean }, window.CAA.enFrDict[clean]);
  }

  // 5. Correspondance dans le cache dynamique (traductions sauvegardées)
  if (window.CAA.dynamicDict && window.CAA.dynamicDict[clean]) {
    return Object.assign({ word: clean }, window.CAA.dynamicDict[clean]);
  }

  // 6. Recherche dans les verbes irréguliers (base, prétérit ou participe)
  if (window.CAA.content && Array.isArray(window.CAA.content.irregularVerbs)) {
    const iv = window.CAA.content.irregularVerbs.find(i => 
      (i.base && i.base.toLowerCase() === clean) ||
      (i.past && i.past.toLowerCase() === clean) ||
      (i.participle && i.participle.toLowerCase() === clean)
    );
    if (iv) {
      const isPast = iv.past && iv.past.toLowerCase() === clean;
      const isPart = iv.participle && iv.participle.toLowerCase() === clean;
      return {
        word: clean,
        fr: iv.fr || "Verbe irrégulier",
        pos: isPast ? "verbe (prétérit)" : (isPart ? "participe passé" : "verbe"),
        tip: `Infinitif: ${iv.base} | Prétérit: ${iv.past} | Participe: ${iv.participle}`
      };
    }
  }

  // 7. Mots composés avec trait d'union (ex: front-row, slow-motion, tree-top, super-strong)
  if (clean.includes("-")) {
    const parts = clean.split("-");
    const translatedParts = parts.map(p => {
      const info = window.CAA.lookupStoryWord(p, storyVocab);
      return info && info.fr ? info.fr.split(",")[0].split("/")[0].trim() : p;
    });
    if (translatedParts.some(p => p !== parts[0])) {
      return {
        word: clean,
        fr: translatedParts.join(" "),
        pos: guessPartOfSpeech(clean),
        tip: `Mot composé : ${parts.join(" + ")}`
      };
    }
  }

  // 8. Lemmatisation linguistique avancée (recherche de la racine dans storyVocab et enFrDict)
  const stems = [];
  
  // Pluriels réguliers et 3e personne (-s, -es, -ies)
  if (clean.endsWith("ies")) stems.push(clean.replace(/ies$/, "y"));
  if (clean.endsWith("es")) stems.push(clean.replace(/es$/, ""));
  if (clean.endsWith("s")) stems.push(clean.replace(/s$/, ""));

  // Passé régulier (-ed, -ied, suppression 'e', dédoublement de consonne)
  if (clean.endsWith("ied")) stems.push(clean.replace(/ied$/, "y"));
  if (clean.endsWith("ed")) {
    stems.push(clean.replace(/ed$/, ""));
    stems.push(clean.replace(/ed$/, "e")); // ex: danced -> dance, smiled -> smile
    // Consonne dédoublée (ex: stepped -> step, hopped -> hop, begged -> beg)
    const withoutEd = clean.replace(/ed$/, "");
    if (withoutEd.length >= 3 && withoutEd[withoutEd.length - 1] === withoutEd[withoutEd.length - 2]) {
      stems.push(withoutEd.slice(0, -1));
    }
  }

  // Forme progressive (-ing, -ying, suppression 'e', dédoublement)
  if (clean.endsWith("ing")) {
    stems.push(clean.replace(/ing$/, ""));
    stems.push(clean.replace(/ing$/, "e")); // ex: making -> make, dancing -> dance
    const withoutIng = clean.replace(/ing$/, "");
    if (withoutIng.length >= 3 && withoutIng[withoutIng.length - 1] === withoutIng[withoutIng.length - 2]) {
      stems.push(withoutIng.slice(0, -1)); // ex: running -> run, swimming -> swim
    }
  }

  // Adverbes en -ly, -ily
  if (clean.endsWith("ily")) stems.push(clean.replace(/ily$/, "y"));
  if (clean.endsWith("ly")) stems.push(clean.replace(/ly$/, ""));

  // Comparatifs et superlatifs (-er, -est)
  if (clean.endsWith("est")) {
    stems.push(clean.replace(/est$/, ""));
    stems.push(clean.replace(/est$/, "e"));
  }
  if (clean.endsWith("er")) {
    stems.push(clean.replace(/er$/, ""));
    stems.push(clean.replace(/er$/, "e"));
  }

  // Préfixes courants (un-, dis-, re-, out-)
  if (clean.startsWith("un") && clean.length > 4) stems.push(clean.slice(2));
  if (clean.startsWith("dis") && clean.length > 5) stems.push(clean.slice(3));
  if (clean.startsWith("re") && clean.length > 4) stems.push(clean.slice(2));
  if (clean.startsWith("out") && clean.length > 5) stems.push(clean.slice(3));

  // Vérifier chaque racine générée
  for (const s of stems) {
    if (storyVocab && storyVocab[s]) {
      const isUn = clean.startsWith("un") && !s.startsWith("un");
      return Object.assign({ word: clean, base: s }, storyVocab[s], {
        fr: isUn ? `non ${storyVocab[s].fr}` : storyVocab[s].fr,
        tip: storyVocab[s].tip || `Forme fléchie de ${s}.`
      });
    }
    if (window.CAA.enFrDict && window.CAA.enFrDict[s]) {
      const baseInfo = window.CAA.enFrDict[s];
      const isUn = clean.startsWith("un") && !s.startsWith("un");
      return Object.assign({ word: clean, base: s }, baseInfo, {
        fr: isUn ? `non ${baseInfo.fr} / sans ${baseInfo.fr}` : baseInfo.fr,
        pos: guessPartOfSpeech(clean),
        tip: baseInfo.tip ? `${baseInfo.tip} (Forme : ${clean})` : `Forme fléchie de ${s}.`
      });
    }
    if (window.CAA.dynamicDict && window.CAA.dynamicDict[s]) {
      return Object.assign({ word: clean, base: s }, window.CAA.dynamicDict[s]);
    }
  }

  // 9. Correspondance dans le vocabulaire global des jeux
  if (window.CAA.content && Array.isArray(window.CAA.content.vocabulary)) {
    const found = window.CAA.content.vocabulary.find(v => v.en && v.en.toLowerCase() === clean);
    if (found) {
      return {
        word: clean,
        fr: found.fr || "Vocabulaire",
        pos: found.cat || "mot",
        tip: found.meaning || `Mot anglais : ${found.en}`
      };
    }
    for (const s of stems) {
      const stemFound = window.CAA.content.vocabulary.find(v => v.en && v.en.toLowerCase() === s);
      if (stemFound) {
        return {
          word: clean,
          fr: stemFound.fr || "Vocabulaire",
          pos: guessPartOfSpeech(clean),
          tip: stemFound.meaning || `Dérivé de ${stemFound.en}`
        };
      }
    }
  }

  // 10. Correspondance dans les verbes à particule
  if (window.CAA.content && Array.isArray(window.CAA.content.phrasalVerbs)) {
    const pv = window.CAA.content.phrasalVerbs.find(p => p.verb && p.verb.toLowerCase().includes(clean));
    if (pv) {
      return {
        word: clean,
        fr: pv.meaningFr || pv.meaningEn || "Verbe à particule",
        pos: "phrasal verb",
        tip: pv.example || pv.verb
      };
    }
  }

  // 11. Déduction intelligente garantie (jamais de valeur vide ou trompeuse)
  const guessedPos = guessPartOfSpeech(clean);
  let fallbackFr = `Vocabulaire anglais : ${clean}`;
  if (rawWord && /^[A-Z][a-z]+$/.test(rawWord) && !["The", "A", "An", "In", "On", "At", "He", "She", "It", "They", "We", "You", "When", "Then", "Suddenly", "Meanwhile", "One", "Two"].includes(rawWord)) {
    fallbackFr = `Nom propre / Personnage (${rawWord})`;
  } else if (clean.endsWith("ly")) {
    fallbackFr = `De manière ${clean.replace(/ly$/, "")} (adverbe)`;
  } else if (clean.endsWith("ing")) {
    fallbackFr = `Action de ${clean.replace(/ing$/, "")} (participe présent)`;
  } else if (clean.endsWith("ed")) {
    fallbackFr = `Forme passée de ${clean.replace(/ed$/, "")}`;
  }

  return {
    word: clean,
    raw: rawWord,
    fr: fallbackFr,
    pendingTranslate: true,
    pos: guessedPos,
    tip: `Mot : ${rawWord}`
  };
};

